#include <stdint.h>
#include <stddef.h>
int valid_frame(const uint8_t *b,size_t len){if(len<2)return 0;size_t n=b[0];if(len!=n+2)return 0;uint8_t s=0;for(size_t i=0;i<n;i++)s=(uint8_t)(s+b[i+1]);return s==b[n+1];}
